mapper.select:
        select
        orders.*,
        users.nick_name
        from orders orders
		left join users users on orders.user_id = users.id

            and orders.id = #{id}
            and orders.order_no = #{orderNo}
            and orders.user_id = #{userId}
            and orders.total_price = #{totalPrice}
            and orders.address = #{address}
            and orders.phone = #{phone}
            and orders.order_type = #{orderType}
            and orders.order_status = #{orderStatus}
            and orders.create_time = #{createTime}
            and orders.remark = #{remark}
            and orders.comment = #{comment}
            and orders.reply = #{reply}
            and users.nick_name like concat('%',#{nickName},'%')

        order by id desc

            limit #{current},#{pageSize}

        select count(*) from orders orders
		left join users users on orders.user_id = users.id

            and orders.id = #{id}
            and orders.order_no = #{orderNo}
            and orders.user_id = #{userId}
            and orders.total_price = #{totalPrice}
            and orders.address = #{address}
            and orders.phone = #{phone}
            and orders.order_type = #{orderType}
            and orders.order_status = #{orderStatus}
            and orders.create_time = #{createTime}
            and orders.remark = #{remark}
            and orders.comment = #{comment}
            and orders.reply = #{reply}
            and users.nick_name like concat('%',#{nickName},'%')
